CREATE OR REPLACE FUNCTION civic.notify_response() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE r civic.reports; lga text; BEGIN IF NEW.data->>'action'='RESPOND_REPORT' THEN SELECT * INTO r FROM civic.reports WHERE id=NEW.data->>'entityId'; SELECT lga_id INTO lga FROM civic.items WHERE id=r.item_id; INSERT INTO civic.notifications SELECT gen_random_uuid()::text,user_id,jsonb_build_object('type','CLARIFICATION_RECEIVED','reportId',r.id,'createdAt',now(),'read',false) FROM civic.memberships WHERE active AND workspace_id=r.workspace_id AND (role='ADMIN' OR (role='MEAL' AND lga=ANY(lga_ids))); END IF; RETURN NEW; END $$;
CREATE TRIGGER response_notification AFTER INSERT ON civic.audit FOR EACH ROW EXECUTE FUNCTION civic.notify_response();
CREATE OR REPLACE FUNCTION civic.request_amendment(p_id text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE m civic.memberships:=civic.require_actor(); r civic.reports; BEGIN SELECT * INTO r FROM civic.reports WHERE id=p_id AND author_id=m.user_id AND workspace_id=m.workspace_id; IF r.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; IF length(trim(coalesce(p_reason,'')))<3 OR length(p_reason)>2000 THEN RAISE EXCEPTION 'REASON_REQUIRED'; END IF; INSERT INTO civic.messages VALUES(gen_random_uuid()::text,p_id,jsonb_build_object('text','Amendment requested: '||p_reason,'visibility','AUTHOR','createdAt',now(),'authorId',m.user_id)); INSERT INTO civic.notifications SELECT gen_random_uuid()::text,user_id,jsonb_build_object('type','AMENDMENT_REQUESTED','reportId',p_id,'createdAt',now(),'read',false) FROM civic.memberships WHERE active AND role='ADMIN' AND workspace_id=m.workspace_id; PERFORM civic.log_event('REQUEST_AMENDMENT',p_id); END $$;
CREATE OR REPLACE FUNCTION civic.record_evidence_access(p_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE m civic.memberships:=civic.require_actor(); BEGIN IF NOT EXISTS(SELECT FROM civic.evidence WHERE id=p_id AND (owner_id=m.user_id OR civic.can_report(report_id))) THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; PERFORM civic.log_event('EVIDENCE_ACCESS',p_id); END $$;
REVOKE ALL ON FUNCTION civic.notify_response(),civic.request_amendment(text,text),civic.record_evidence_access(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION civic.request_amendment(text,text),civic.record_evidence_access(text) TO arewa_app;
